android.extraProguardRules:
# WorkManager creates its Room database reflectively; R8 removed the constructor and 2.1.1 crashed on launch.
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class androidx.work.impl.** { *; }
# sherpa-onnx native code looks up its Java config fields by name; R8 renamed them and choosing an AI voice crashed 2.1.2.
-keep class com.k2fsa.sherpa.onnx.** { *; }
